SOURCE=dict(contractVersion=1,romSha256=FIXTURE['896']['romSha256'],overlaySha256=FIXTURE['896']['pokemonCombat']['identity']['overlaySha256'],profileSha256='c'*64)

def meter():
    m=HeldThrowSearchMeasurement(SOURCE);initial=deepcopy(FIXTURE['768'])
    m.latest=deepcopy(FIXTURE['895']);m.setup_index=len(SETUP)
    m.data.update(carrier=select_current_actor(initial,next(a for a in initial['actors'] if a['species']==74)),cargo=select_current_actor(FIXTURE['895'],next(a for a in FIXTURE['895']['actors'] if a['species']==179)),passive=select_current_actor(initial,next(a for a in initial['actors'] if a['species']==234)),context=deepcopy(initial['context']))
    m.subjects={name:deepcopy(m.data[key]) for name,key in (('geodude','carrier'),('mareep','cargo'),('stantler','passive'))}
    m._profile_events(FIXTURE['profiles'])
    m._profile_events([e for e in FIXTURE['events'] if e['data'].get('actor',{}).get('slot')==7])
    for s in FIXTURE['escape']:m._escape_sample(deepcopy(s))
    assert m.escape is not None
    m.carried_frame=895
    return m

def rows():
    held=[]
    for f in range(896,1097):
        s=deepcopy(FIXTURE['896']);s.update(frame=f,nativeCycle=f+1600,actorFrame=f-435)
        for value in (s['pokemonCombat'],s['pokemonCombat']['interactions']):value.update(frame=f,nativeCycle=f+1600)
        held.append(s)
    release=[]
    for f in range(1097,1148):
        s=deepcopy(FIXTURE['1126'] if f>=1126 else FIXTURE['896'])
        if f==1147:s=deepcopy(FIXTURE['1147'])
        s.update(frame=f,nativeCycle=f+1600,actorFrame=f-435)
        for value in (s['pokemonCombat'],s['pokemonCombat']['interactions']):value.update(frame=f,nativeCycle=f+1600)
        if 1126<=f<=1146:
            s['pokemonCombat']['movementTimers'][0]['movementCooldown']=max(0,20-(f-1126))
        release.append(s)
    result=[]
    for action,samples in (('hold-without-line',held),('open-current-line',release)):
        result.append(dict(phase='observe',action=action,samples=samples,events=[e for e in FIXTURE['events'] if samples[0]['frame']<=e['frame']<=samples[-1]['frame'] and e['data'].get('actor',{}).get('slot')==2],completedGameFrames=len(samples),observedFieldFrames=len(samples),nativeCycles=len(samples),cycleIntervals=[dict(completedGameFrame=s['frame'],cpuNs=1,wallNs=1) for s in samples]))
    return result

def evaluate(records=None,negative=None):
    m=meter();m.latest['nativeCycle']=895+1600
    for row in records or rows():m.observe_record(negative.mutate(row,m.subjects) if negative else row)
    r=m.finish();return dict(passed=r['passed'],failures=r['failures'],observedFrames=r['observedFrames'],measurements={KIND:r})

class HeldThrowSearchTests(unittest.TestCase):
    def test_201_current_held_frames_windup_and_protected_native_start(self):
        r=evaluate();self.assertTrue(r['passed'],r['failures'])
        result=r['measurements'][KIND];self.assertEqual(result['continuousHeldFrames'],201)
        self.assertEqual((result['heldStart'],result['heldEnd']),(896,1096))
        self.assertEqual(result['launch']['frame'],1147)
        self.assertEqual(len(measurements(r,dict(sessionId='owned',sessionCleanup=dict(sessionId='owned',closed=True,errors=[])))),5)

    def test_all_named_copied_faults_reject_at_their_guard(self):
        for fault in FAULTS:
            with self.subTest(fault=fault):
                n=HeldThrowSearchNegative(fault);r=evaluate(negative=n)
                self.assertTrue(n.applied);validate_negative_result(r,fault)

    def test_short_hold_stale_start_and_uncleared_binding_cannot_launch(self):
        for fault in ('short','stale-start','binding'):
            with self.subTest(fault=fault):
                data=rows()
                if fault=='short':data[0]['samples'].pop();data[0]['completedGameFrames']-=1;data[0]['observedFieldFrames']-=1;data[0]['nativeCycles']-=1;data[0]['cycleIntervals'].pop()
                elif fault=='stale-start':next(e for e in data[1]['events'] if e['data']['event']=='MOTION_STARTED')['frame']-=1
                else:
                    target=data[1]['samples'][-1]['pokemonCombat']['interactions']['carriers'][0]
                    target['bindings']=deepcopy(FIXTURE['1126']['pokemonCombat']['interactions']['carriers'][0]['bindings']);target['rawBindingsHex']=FIXTURE['1126']['pokemonCombat']['interactions']['carriers'][0]['rawBindingsHex']
                self.assertFalse(evaluate(data)['passed'])

    def test_missing_completed_fence_hop_and_prepared_recipe_changes_reject(self):
        m=meter();m.escape=None
        for row in rows():m.observe_record(row)
        self.assertFalse(m.finish()['passed'])
        path=HERE.parents[1]/'tests/overworld/test-recipes/wild.throw-held-search.json'
        r=json.loads(path.read_text());validate_recipe(r)
        r['actions'][1]['args']['frames']=200
        with self.assertRaises(ValueError):validate_recipe(r)

    def test_existing_factory_registration_and_reader_optin_are_exact(self):
        for name in ('devtools_test_contract','devtools_test_inputs','proof_adapters'):
            spec=importlib.util.spec_from_file_location('tools.overworld.'+name,HERE/(name+'.py'))
            module=importlib.util.module_from_spec(spec);sys.modules[spec.name]=module;spec.loader.exec_module(module)
        from tools.overworld.devtools_test_contract import TestEvaluator,validate_test
        from tools.overworld.devtools_test_inputs import measurement_inputs
        from tools.overworld.proof_adapters import get_adapter
        from tools.overworld.control import _shared_test_registration
        repo=HERE.parents[1]
        recipe=validate_test(json.loads((repo/'tests/overworld/test-recipes/wild.throw-held-search.json').read_text()))
        registration,_=_shared_test_registration(recipe,repo)
        source=measurement_inputs(recipe,ROOT)
        self.assertEqual(set(source[KIND]),set(SOURCE))
        evaluator=TestEvaluator(recipe);evaluator.install_measurements(source)
        self.assertIsInstance(evaluator.measurements[KIND],HeldThrowSearchMeasurement)
        adapter=get_adapter(KIND)
        self.assertEqual(adapter.contract(),registration['measurementContract'])
        self.assertEqual(adapter.recipe_subjects(),recipe['subjects'])
        jobs=(HERE/'devtools_jobs.py').read_text()
        self.assertIn('("held-throw-search-v1", "follower-throw-moving-cargo-v1"',jobs)
        self.assertIn('record_args["throwInteractions"] = True',jobs)
        self.assertIn('evaluator.observe_record(row)',jobs)

    def test_normal_select_handoff_keeps_full_subject_before_observation(self):
        m=meter();m.setup_index=6;m.data['cargo']=None;m.subjects.pop('mareep')
        snap=deepcopy(FIXTURE['867']);old=deepcopy(m.subjects['stantler'])
        with self.assertRaises(ValueError):select_current_actor(snap,old)
        receipt=dict(normalInputOnly=True,gardenEscape=deepcopy(m.escape))
        result=m.observe_record(dict(phase='setup',action='normal-pocket-exit',command='held-throw-pocket.prepare',snapshot=snap,receipt=receipt))
        self.assertFalse(result['failures'],result['failures'])
        new=result['subjects']['stantler'];self.assertEqual(new['handle'],old['handle'])
        self.assertEqual(new['subjectIdentity'],old['subjectIdentity'])
        select_current_actor(snap,new)
        for fault in ('permission','same-handle'):
            bad=meter();bad.setup_index=6;bad.data['cargo']=None;bad.subjects.pop('mareep')
            sample=deepcopy(snap);proof=deepcopy(receipt)
            if fault=='permission':proof['normalInputOnly']=False
            else:next(a for a in sample['actors'] if a['species']==234)['handle']['generation']+=1
            value=bad.observe_record(dict(phase='setup',action='normal-pocket-exit',command='held-throw-pocket.prepare',snapshot=sample,receipt=proof))
            self.assertTrue(value['failures'],fault)

if __name__=='__main__':unittest.main()
